using UnityEngine;using System.Collections;using System.IO;
public class HunterActionReview:MonoBehaviour{
 public Animator animator;public Camera view;public bool automaticCapture=true;string current="Idle";
 void Update(){string[] names={"Idle","Walk","Run","Dodge","Attack","Hit","Death","Interaction"};for(int i=0;i<8;i++)if(Input.GetKeyDown(KeyCode.Alpha1+i))Play(names[i]);if(Input.GetKey(KeyCode.Q))view.transform.RotateAround(Vector3.up,Vector3.up,-60*Time.deltaTime);if(Input.GetKey(KeyCode.E))view.transform.RotateAround(Vector3.up,Vector3.up,60*Time.deltaTime);}
 public void Play(string state){current=state;animator.speed=1;animator.Play(state,0,0);}
 IEnumerator Start(){animator.applyRootMotion=false;if(!automaticCapture)yield break;string dir=Path.GetFullPath("Evidence/hunter-actions-playmode");Directory.CreateDirectory(dir);File.WriteAllText(dir+"/states.txt","Unity "+Application.unityVersion+"\nRoot Motion false. Normal-speed isolated action review.\n");string[] states={"Attack","Dodge","Hit","Death","Interaction"};foreach(string s in states){view.transform.position=new Vector3(2.6f,1.4f,2.6f);view.transform.LookAt(Vector3.up);Play(s);for(int f=0;f<4;f++){view.transform.position=Quaternion.Euler(0,f*90,0)*new Vector3(0,1.4f,3.6f);view.transform.LookAt(Vector3.up);yield return new WaitForSeconds(.22f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(dir+"/"+s+"_"+f+".png");File.AppendAllText(dir+"/states.txt",s+" sample="+f+" state="+animator.GetCurrentAnimatorStateInfo(0).shortNameHash+" root="+transform.position+"\n");}yield return new WaitForSeconds(1.6f);}Play("Idle");}
 void OnGUI(){GUI.Box(new Rect(16,16,600,65),"Hunter actions | "+current+"\n1 Idle 2 Walk 3 Run 4 Dodge 5 Attack 6 Hit 7 Death 8 Interact | Q/E orbit");}
}
